#include <bits/stdc++.h>
#define IOS ios::sync_with_stdio(0)
#define lowbit(x) ((x) & (-x))
#define int long long
using namespace std;

inline char gc() {
    static char buf[1000000], *p1 = buf, *p2 = buf;
    return p1 == p2 && (p2 = (p1 = buf) + fread(buf, 1, 1000000, stdin), p1 == p2) ? EOF : *p1++;
}

int read() {
    int sign = 1, num = 0;
    char ch = getchar();
    while (!isdigit(ch)) {
        if (ch == '-') sign = -1;
        ch = getchar();
    }
    while (isdigit(ch)) {
        num = num * 10 + (ch - '0');
        ch = getchar();
    }
    return sign * num;
}

void write(int x) {
    if (x < 0) {
        putchar('-');
        write(-x);
        return;
    }
    if (x >= 10) write(x / 10);
    putchar(x % 10 + '0');
}

void writesp(int x) {
    write(x);
    putchar(' ');
}

void writeln(int x) {
    write(x);
    putchar('\n');
}

const int mod1 = 998244353, mod2 = 1000000007;
vector<int> val[10];
int n, cnt1, cnt2, ans, sum[10], Pow[7] = {1, 10, 100, 1000, 10000, 100000, 1000000};

bool check(int x) {
    int now = 1000000;
    return x * now + 999999 <= n && x * now * 10 > n;
}

void dfs1(int x1, int x2) {
    if (x1 == 7) return;
    val[x1].emplace_back((cnt1 - x2 + mod1) % mod1);
    sum[x1] += (cnt1 - x2 + mod1) % mod1;
    cnt1++;
    for (int i = 0; i <= 9; i++)
        dfs1(x1 + 1, x2 * 10 + i);
}

void dfs2(int x1, int x2) {
    if (x2 > n) return;
    if (check(x2)) {
        for (int i = 0; i <= 6; i++) {
            int now = ((cnt2 + 1 - (x2 * Pow[i])) % mod1 + mod1) % mod1;
            int pos = lower_bound(val[i].begin(), val[i].end(), mod1 - now) - val[i].begin();
            ans = (ans + (sum[i] + now * (int)val[i].size() - mod1 * ((int)val[i].size() - pos))) % mod2;
        }
        cnt2 += cnt1;
    } else {
        cnt2++;
        ans = (ans + ((cnt2 - x2) % mod1 + mod1) % mod1) % mod2;
        for (int i = (!x1); i <= 9; i++)
            dfs2(x1 + 1, x2 * 10 + i);
    }
}

signed main() {
    n = read();
    dfs1(0, 0);
    for (int i = 0; i <= 6; i++)
        sort(val[i].begin(), val[i].end());
    cnt2 = -1;
    dfs2(0, 0);
    writeln(ans);
}
